    if (data <= data_) {
        if (left_) {
            left_->insert(data);
        } else {
            left_ = std::make_unique<tree>(data);
        }
    } else {
        if (right_) {
            right_->insert(data);
        } else {
            right_ = std::make_unique<tree>(data);
        }
    }
}

bool tree::contains(int data) const {
    if (data == data_) {
        return true;
    }

    if (data < data_) {
        return left_ && left_->contains(data);
    }

    return right_ && right_->contains(data);
}

